pub fn min_cutting_cost(n: i32, m: i32, k: i32) -> i64 {
    let n = n as i64;
    let m = m as i64;
    let k = k as i64;

    if n <= k && m <= k {
        return 0;
    }

    let mut cost = 0;

    if n > k {
        let mut best_cost = n * (n - k);
        for i in 1..n {
            let len1 = i as i64;
            let len2 = n - i;
            let current_cost = len1 * len2;
            best_cost = best_cost.min(current_cost);
        }
        cost += best_cost;
    }

    if m > k {
        let mut best_cost = m * (m - k);
        for i in 1..m {
            let len1 = i as i64;
            let len2 = m - i;
            let current_cost = len1 * len2;
            best_cost = best_cost.min(current_cost);
        }
        cost += best_cost;
    }

    cost
}
